local UICultivateEquipSuitInfoNode = Class('UICultivateEquipSuitInfoNode')


------------ define ------------
local AniTime      = 0.3
local AniDelayTime = 0.03
local UICultivateCareerTypeNodePath = "Game.UI.Cultivate.UICultivateCareerTypeNode"
------------ define ------------

------------ import ------------
local DOTween               = CS.DG.Tweening.DOTween
------------ import ------------

function UICultivateEquipSuitInfoNode:__init()
    self.suitPart = nil

end

function UICultivateEquipSuitInfoNode:__delete()
    self.suitPart = nil
end

function UICultivateEquipSuitInfoNode:Awake()
    SetButtonAction(self.Background.gameObject, Bind(self, self.OnClickBackgroundAction))
end

function UICultivateEquipSuitInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


