---RefreshUI
---@param suitData table {suitId, name, desc, iconPath}
---@param ownEquipPartMap table<number, number>
function UICultivateEquipSuitInfoNode:RefreshUI(suitData, ownEquipPartMap, showType, position)

    local data  = ownEquipPartMap
    local count = 0
    if showType == 1 then
        count = #data
    else
        for part, ids in pairs(ownEquipPartMap) do
            count = #ids + count
        end
    end
    local isOwnSuitPart = count > 0

    self.NameText.text = suitData.name
    self:RefreshCoreType(suitData.occupationId)

    self.SuitIcon:LoadSprite(suitData.iconPath)

    self.OwnNumText.text = string.format("x%s", count)

    --self.TxtAvailable.Status = isOwnSuitPart and 1 or 2

    self.Background.alpha = isOwnSuitPart and 1 or 0.5

    self.position = position
    self.count = count
end

---RefreshCoreType
---@param occupationId number   职业id
function UICultivateEquipSuitInfoNode:RefreshCoreType(occupationId)
    ---@type UICultivateCareerTypeNode
    local mbEnv = CfUtils.GetLuaScr(self.TypeBg.gameObject, UICultivateCareerTypeNodePath)
    if mbEnv == nil then
        return
    end

    mbEnv:RefreshUI(occupationId)
end

function UICultivateEquipSuitInfoNode:ShowAnimate(index)
    ---------------------------
    --- 动画初始设置
    ---@type UnityEngine.Transform
    local containerTrans = self.Container.transform
    local canvasGroup = self.Container
    canvasGroup.alpha = 0

    local localPosition = containerTrans.localPosition
    containerTrans.localPosition = Vector3.New(localPosition.x, localPosition.y - 45, localPosition.z)

    ---------------------------
    --- 播放动画
    local sequence = DOTween:Sequence()
    local moveAni  = containerTrans:DOLocalMoveY(localPosition.y, AniTime):SetDelay(AniDelayTime * index)
    local fadeAni  = canvasGroup:DOFade(1, AniTime):SetDelay(AniDelayTime * index)
    sequence:Append(moveAni)
    sequence:Join(fadeAni)
end

